// Agrupar emails por categoría y crear resumen
const items = $input.all();

const categories = {
  client: { name: 'CLIENTE 🔵', emails: [], count: 0 },
  billing: { name: 'FACTURAS 💰', emails: [], count: 0 },
  lead: { name: 'LEAD 🟢', emails: [], count: 0 },
  internal: { name: 'INTERNO 🟡', emails: [], count: 0 },
  spam: { name: 'SPAM 🔴', emails: [], count: 0 }
};

// Agrupar por categoría
items.forEach(item => {
  const cat = item.json.category;
  if (categories[cat]) {
    categories[cat].count++;
    categories[cat].emails.push({
      from: item.json.from,
      subject: item.json.subject,
      preview: item.json.body.substring(0, 100) + '...'
    });
  }
});

// Crear resumen
let summary = '\n═══════════════════════════════════════════════\n';
summary += '    📧 GENERADOR DE EMAILS DEMO - RESUMEN\n';
summary += '═══════════════════════════════════════════════\n\n';
summary += `Total de emails generados: ${items.length}\n\n`;

Object.entries(categories).forEach(([key, cat]) => {
  if (cat.count > 0) {
    summary += `\n${cat.name}\n`;
    summary += `${'─'.repeat(40)}\n`;
    summary += `Cantidad: ${cat.count} emails\n\n`;

    cat.emails.forEach((email, idx) => {
      summary += `  ${idx + 1}. ${email.subject}\n`;
      summary += `     De: ${email.from}\n`;
      summary += `     Preview: ${email.preview}\n\n`;
    });
  }
});

summary += '\n═══════════════════════════════════════════════\n';
summary += 'Para enviar estos emails, conecta un nodo Gmail\n';
summary += 'o utilízalos para testing del workflow principal\n';
summary += '═══════════════════════════════════════════════\n';

return [{
  json: {
    total_emails: items.length,
    categories: {
      client: categories.client.count,
      billing: categories.billing.count,
      lead: categories.lead.count,
      internal: categories.internal.count,
      spam: categories.spam.count
    },
    summary: summary,
    all_emails: items.map(i => i.json)
  }
}];

// Delay configurable entre envíos para no saturar
const delaySeconds = parseInt($('⚙️ Config Email Sender').first().json.DELAY_SECONDS) || 2;
await new Promise(resolve => setTimeout(resolve, delaySeconds * 1000));
return $input.all();

