// Generar reporte final de envío
const sentItems = $input.first().json.status ? [$input.first()] : [];
const notSentItems = $input.last().json.status ? [] : $input.all();

const totalSent = sentItems.length;
const totalNotSent = notSentItems.length;

let report = '\n';
report += '╔══════════════════════════════════════════════════════╗\n';
report += '║       📧 REPORTE DE ENVÍO DE EMAILS DEMO           ║\n';
report += '╚══════════════════════════════════════════════════════╝\n';
report += '\n';

if (totalSent > 0) {
  report += `✅ EMAILS ENVIADOS: ${totalSent}\n`;
  report += `${'─'.repeat(54)}\n`;
  sentItems.forEach((item, idx) => {
    report += `  ${idx + 1}. ${item.json.category} - ${item.json.subject}\n`;
    report += `     📤 Enviado a: ${item.json.sent_to}\n`;
    report += `     🕐 ${item.json.sent_at}\n\n`;
  });
} else {
  report += '❌ No se enviaron emails\n';
  report += '   (SEND_EMAILS está configurado como "false")\n\n';
  report += '💡 Para activar el envío:\n';
  report += '   1. Edita el nodo "⚙️ Config Email Sender"\n';
  report += '   2. Cambia SEND_EMAILS a "true"\n';
  report += '   3. Configura TARGET_EMAIL con tu email\n';
  report += '   4. Configura credenciales de Gmail\n';
}

report += '\n';
report += `${'═'.repeat(54)}\n`;
report += `📊 Total emails generados: ${totalSent + totalNotSent}\n`;
report += `📤 Enviados: ${totalSent}\n`;
report += `📥 No enviados: ${totalNotSent}\n`;
report += `${'═'.repeat(54)}\n`;

return [{
  json: {
    report: report,
    total_generated: totalSent + totalNotSent,
    total_sent: totalSent,
    total_not_sent: totalNotSent,
    sent_emails: sentItems.map(i => i.json),
    timestamp: new Date().toISOString()
  }
}];
